<?php
require_once __DIR__ . '/auth.php';
if (!current_user()) { header('Location: login.php'); exit; }
if (!has_owner()) {
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['activate_owner'])) { make_current_user_owner(); header('Location: admin.php'); exit; }
    ?>
    <!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ativar loja — Vértice</title><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="admin.css"></head><body class="admin-page"><main class="setup-card"><p class="eyebrow">CONFIGURAÇÃO INICIAL</p><h1>Ativar área<br>do proprietário</h1><p>Você será o administrador da loja e poderá cadastrar produtos, editar preços e controlar o estoque.</p><form method="post"><button class="button" name="activate_owner" value="1">Ativar meu acesso <span>→</span></button></form><a href="index.php">Voltar para a loja</a></main></body></html>
    <?php exit;
}
if (!is_owner()) { http_response_code(403); exit('Esta área é exclusiva do proprietário da loja.'); }

$connection = db(); $message = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    if ($action === 'delete') {
        $id = (int) ($_POST['id'] ?? 0); $statement = $connection->prepare('DELETE FROM products WHERE id = ?'); $statement->bind_param('i', $id); $statement->execute(); $message = 'Produto excluído do catálogo.';
    }
    if ($action === 'save') {
        $id = (int) ($_POST['id'] ?? 0); $name = trim($_POST['name'] ?? ''); $category = trim($_POST['category'] ?? ''); $price = (float) ($_POST['price'] ?? 0); $oldPrice = (float) ($_POST['old_price'] ?? 0); $stock = (int) ($_POST['stock'] ?? 0); $image = trim($_POST['image'] ?? ''); $description = trim($_POST['description'] ?? '');
        if (!$name || !$category || $price <= 0 || $stock < 0 || !$image || !$description) $error = 'Preencha todos os campos obrigatórios corretamente.';
        else {
            if ($oldPrice <= 0) $oldPrice = $price;
            if ($id > 0) { $statement = $connection->prepare('UPDATE products SET name=?, category=?, price=?, old_price=?, image=?, description=?, stock=? WHERE id=?'); $statement->bind_param('ssddssii', $name, $category, $price, $oldPrice, $image, $description, $stock, $id); $statement->execute(); $message = 'Produto atualizado com sucesso.'; }
            else { $statement = $connection->prepare('INSERT INTO products (name, category, price, old_price, image, description, stock) VALUES (?, ?, ?, ?, ?, ?, ?)'); $statement->bind_param('ssddssi', $name, $category, $price, $oldPrice, $image, $description, $stock); $statement->execute(); $message = 'Novo produto cadastrado com sucesso.'; }
        }
    }
}
$edit = ['id' => '', 'name' => '', 'category' => 'Feminino', 'price' => '', 'old_price' => '', 'image' => '', 'description' => '', 'stock' => 0];
if (isset($_GET['edit'])) { $id = (int) $_GET['edit']; $statement = $connection->prepare('SELECT * FROM products WHERE id=?'); $statement->bind_param('i', $id); $statement->execute(); $found = $statement->get_result()->fetch_assoc(); if ($found) $edit = $found; }
$products = $connection->query('SELECT * FROM products ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel da loja — Vértice</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="admin.css"></head><body class="admin-page"><header class="admin-header"><a class="brand" href="index.php"><b>V</b><span>vértice</span></a><div><span>Olá, <?php echo htmlspecialchars(current_user()['name']); ?></span><a href="index.php">Ver loja</a><a href="logout.php">Sair</a></div></header><main class="admin-main"><section class="admin-intro"><div><p class="eyebrow">PAINEL DO PROPRIETÁRIO</p><h1>Produtos e estoque</h1><p>Cadastre as peças da sua loja e mantenha a quantidade disponível sempre atualizada.</p></div><div class="admin-summary"><strong><?php echo count($products); ?></strong><span>produtos cadastrados</span><strong><?php echo array_sum(array_column($products, 'stock')); ?></strong><span>itens em estoque</span></div></section><?php if ($message): ?><div class="admin-message success"><?php echo $message; ?></div><?php endif; ?><?php if ($error): ?><div class="admin-message error"><?php echo $error; ?></div><?php endif; ?><section class="admin-grid"><form class="product-form" method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo htmlspecialchars((string) $edit['id']); ?>"><div class="form-title"><h2><?php echo $edit['id'] ? 'Editar produto' : 'Adicionar produto'; ?></h2><?php if ($edit['id']): ?><a href="admin.php">Cancelar edição</a><?php endif; ?></div><label>Nome do produto<input required name="name" value="<?php echo htmlspecialchars($edit['name']); ?>" placeholder="Ex.: Camiseta básica"></label><div class="form-row"><label>Categoria<select name="category"><option <?php echo $edit['category']==='Feminino'?'selected':''; ?>>Feminino</option><option <?php echo $edit['category']==='Masculino'?'selected':''; ?>>Masculino</option><option <?php echo $edit['category']==='Acessórios'?'selected':''; ?>>Acessórios</option><option <?php echo $edit['category']==='Calçados'?'selected':''; ?>>Calçados</option></select></label><label>Quantidade em estoque<input required min="0" type="number" name="stock" value="<?php echo (int) $edit['stock']; ?>"></label></div><div class="form-row"><label>Preço atual (R$)<input required min="0.01" step="0.01" type="number" name="price" value="<?php echo htmlspecialchars((string) $edit['price']); ?>"></label><label>Preço anterior (R$)<input min="0" step="0.01" type="number" name="old_price" value="<?php echo htmlspecialchars((string) $edit['old_price']); ?>"></label></div><label>Link da imagem<input required type="url" name="image" value="<?php echo htmlspecialchars($edit['image']); ?>" placeholder="https://..."></label><label>Descrição<textarea required name="description" placeholder="Descreva o produto"><?php echo htmlspecialchars($edit['description']); ?></textarea></label><button class="button" type="submit"><?php echo $edit['id'] ? 'Salvar alterações' : 'Cadastrar produto'; ?><span>→</span></button></form><section class="product-list"><div class="form-title"><h2>Catálogo</h2><span><?php echo count($products); ?> itens</span></div><?php foreach ($products as $product): ?><article class="admin-product"><img src="<?php echo htmlspecialchars($product['image']); ?>" alt=""><div><small><?php echo htmlspecialchars($product['category']); ?></small><h3><?php echo htmlspecialchars($product['name']); ?></h3><p>R$ <?php echo number_format((float)$product['price'], 2, ',', '.'); ?> · <b><?php echo (int)$product['stock']; ?> em estoque</b></p></div><aside><a href="admin.php?edit=<?php echo $product['id']; ?>">Editar</a><form method="post" onsubmit="return confirm('Excluir este produto?');"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo $product['id']; ?>"><button type="submit">Excluir</button></form></aside></article><?php endforeach; ?></section></section></main></body></html>
